// VALIDAR DISPONIBILIDAD - VERSIÓN COMPLETA Y FUNCIONANDO
// Este nodo reemplaza tanto a "Validar Input1" como a "Validar Disponibilidad1"
// Mode: Run Once for All Items

// ========================================
// 1. OBTENER DATOS DE PARSE INPUT
// ========================================
const parseInputNode = $('Parse Input');
let input;

try {
  input = parseInputNode.first().json;
  console.log('📥 Input de Parse Input:', JSON.stringify(input, null, 2));
} catch (error) {
  throw new Error('❌ No se pudo leer Parse Input. Asegúrate que el nodo Parse Input se ejecutó correctamente. Error: ' + error.message);
}

// ========================================
// 2. VALIDAR QUE PARSE INPUT TIENE DATOS
// ========================================
if (!input || !input.divisa_origen || !input.cantidad_origen || !input.divisa_destino) {
  throw new Error(`❌ Parse Input tiene datos incompletos:\n${JSON.stringify(input, null, 2)}\n\nDebe tener: divisa_origen, cantidad_origen, divisa_destino`);
}

// ========================================
// 3. OBTENER STOCKS DISPONIBLES
// ========================================
const stocksData = $input.all().map(item => item.json);
console.log('📊 Stocks disponibles:', stocksData.length, 'divisas');
console.log('📊 Divisas:', stocksData.map(s => s.divisa).join(', '));

// ========================================
// 4. BUSCAR STOCKS DE LAS DIVISAS
// ========================================
const stockOrigen = stocksData.find(s => s.divisa === input.divisa_origen);
const stockDestino = stocksData.find(s => s.divisa === input.divisa_destino);

console.log('🔍 Buscando:', input.divisa_origen, '→', input.divisa_destino);
console.log('🔍 Stock origen:', stockOrigen ? `${stockOrigen.divisa} (${stockOrigen.stock_disponible})` : '❌ NO ENCONTRADO');
console.log('🔍 Stock destino:', stockDestino ? `${stockDestino.divisa} (${stockDestino.stock_disponible})` : '❌ NO ENCONTRADO');

// Validar que existan ambas divisas
if (!stockOrigen || !stockDestino) {
  const divisaFaltante = !stockOrigen ? input.divisa_origen : input.divisa_destino;
  console.log('❌ Divisa no encontrada:', divisaFaltante);

  return [{
    json: {
      ...input,
      success: false,
      debe_escalar: true,
      message: `❌ *DIVISA NO ENCONTRADA*\n\nLa divisa ${divisaFaltante} no existe en el sistema.\n\nDivisas disponibles: ${stocksData.map(s => s.divisa).join(', ')}\n\n⏳ Un operador revisará tu solicitud.`,
      tipo_escalamiento: 'divisa_invalida',
      stockOrigen: stockOrigen || null,
      stockDestino: stockDestino || null
    }
  }];
}

// ========================================
// 5. CALCULAR CANTIDAD DESTINO
// ========================================
let cantidad_destino = input.cantidad_destino || 0;

if (!cantidad_destino || cantidad_destino === 0) {
  console.log('📊 Calculando cantidad_destino automáticamente...');

  const precio_origen = parseFloat(stockOrigen.precio_compra);
  const precio_destino = parseFloat(stockDestino.precio_venta);

  if (input.divisa_origen === 'USD' && input.divisa_destino === 'ARS') {
    cantidad_destino = input.cantidad_origen * precio_destino;
    console.log(`   USD → ARS: ${input.cantidad_origen} * ${precio_destino} = ${cantidad_destino}`);
  } else if (input.divisa_origen === 'ARS' && input.divisa_destino === 'USD') {
    cantidad_destino = input.cantidad_origen / precio_destino;
    console.log(`   ARS → USD: ${input.cantidad_origen} / ${precio_destino} = ${cantidad_destino}`);
  } else {
    cantidad_destino = (input.cantidad_origen * precio_origen) / precio_destino;
    console.log(`   ${input.divisa_origen} → ${input.divisa_destino}: (${input.cantidad_origen} * ${precio_origen}) / ${precio_destino} = ${cantidad_destino}`);
  }

  cantidad_destino = Math.round(cantidad_destino * 100) / 100;
}

console.log(`✅ Cantidad destino final: ${cantidad_destino} ${input.divisa_destino}`);

// ========================================
// 6. CALCULAR NUEVOS STOCKS
// ========================================
const nuevoStockOrigen = parseFloat(stockOrigen.stock_disponible) + input.cantidad_origen;
const nuevoStockDestino = parseFloat(stockDestino.stock_disponible) - cantidad_destino;

console.log(`📊 Stock ${input.divisa_origen}: ${stockOrigen.stock_disponible} + ${input.cantidad_origen} = ${nuevoStockOrigen}`);
console.log(`📊 Stock ${input.divisa_destino}: ${stockDestino.stock_disponible} - ${cantidad_destino} = ${nuevoStockDestino}`);

// ========================================
// 7. VALIDACIÓN: STOCK INSUFICIENTE
// ========================================
if (nuevoStockDestino < 0) {
  const faltante = Math.abs(nuevoStockDestino);
  console.log(`❌ Stock insuficiente: falta ${faltante} ${input.divisa_destino}`);

  return [{
    json: {
      ...input,
      cantidad_destino: cantidad_destino,
      success: false,
      debe_escalar: true,
      message: `🔴 *STOCK INSUFICIENTE*\n\nNo hay suficiente ${input.divisa_destino}.\n\n📊 Disponible: ${parseFloat(stockDestino.stock_disponible).toLocaleString('es-AR', { maximumFractionDigits: 2 })}\n📉 Necesita: ${cantidad_destino.toLocaleString('es-AR', { maximumFractionDigits: 2 })}\n❌ Faltante: ${faltante.toLocaleString('es-AR', { maximumFractionDigits: 2 })}`,
      tipo_escalamiento: 'stock_insuficiente',
      stockOrigen,
      stockDestino
    }
  }];
}

// ========================================
// 8. VALIDACIÓN: STOCK CRÍTICO
// ========================================
const STOCK_MINIMO = input.divisa_destino === 'ARS' ? 50000 : (input.divisa_destino === 'USD' ? 100 : 10);

if (nuevoStockDestino < STOCK_MINIMO && nuevoStockDestino >= 0) {
  console.log(`⚠️ Stock crítico: ${nuevoStockDestino} < ${STOCK_MINIMO}`);

  return [{
    json: {
      ...input,
      cantidad_destino: cantidad_destino,
      success: false,
      debe_escalar: true,
      message: `⚠️ *STOCK CRÍTICO*\n\nLa operación dejaría el stock de ${input.divisa_destino} muy bajo.\n\n📊 Actual: ${parseFloat(stockDestino.stock_disponible).toLocaleString('es-AR', { maximumFractionDigits: 2 })}\n📉 Después: ${nuevoStockDestino.toLocaleString('es-AR', { maximumFractionDigits: 2 })}\n🔴 Mínimo: ${STOCK_MINIMO.toLocaleString('es-AR', { maximumFractionDigits: 2 })}`,
      tipo_escalamiento: 'stock_critico',
      stockOrigen,
      stockDestino,
      nuevoStockDestino
    }
  }];
}

// ========================================
// 9. VALIDACIÓN: MONTO MÁXIMO
// ========================================
const MONTO_MAXIMO = 2000000;

let valorOperacion;
if (input.divisa_destino === 'ARS') {
  valorOperacion = cantidad_destino;
} else if (input.divisa_origen === 'ARS') {
  valorOperacion = input.cantidad_origen;
} else {
  const precioVentaARS = parseFloat(stockDestino.precio_venta);
  valorOperacion = cantidad_destino * precioVentaARS;
}

console.log(`💰 Valor de la operación: ${valorOperacion.toLocaleString('es-AR')} ARS`);

if (valorOperacion > MONTO_MAXIMO) {
  console.log(`⚠️ Monto alto: ${valorOperacion} > ${MONTO_MAXIMO}`);

  return [{
    json: {
      ...input,
      cantidad_destino: cantidad_destino,
      success: false,
      debe_escalar: true,
      message: `💰 *MONTO ALTO*\n\nEl valor supera el límite automático.\n\n💵 Operación: $${valorOperacion.toLocaleString('es-AR', { maximumFractionDigits: 2 })}\n🔒 Límite: $${MONTO_MAXIMO.toLocaleString('es-AR')}`,
      tipo_escalamiento: 'monto_alto',
      stockOrigen,
      stockDestino,
      valorOperacion
    }
  }];
}

// ========================================
// 10. ✅ TODO OK - CONTINUAR
// ========================================
console.log('✅ Todas las validaciones pasaron correctamente');

return [{
  json: {
    ...input,
    cantidad_destino: cantidad_destino,
    success: true,
    debe_escalar: false,
    stockOrigen,
    stockDestino,
    nuevoStockOrigen,
    nuevoStockDestino,
    valorOperacion,
    idStockOrigen: stockOrigen.id,
    idStockDestino: stockDestino.id
  }
}];

const data = $('Validar Disponibilidad1').first().json;

return {
  json: {
    success: true,
    debe_escalar: false,
    message: `✅ *OPERACIÓN COMPLETADA*
━━━━━━━━━━━━━━━━━━

📤 Entregaste: ${data.cantidad_origen.toLocaleString('es-AR')} ${data.divisa_origen}
📥 Recibiste: ${data.cantidad_destino.toLocaleString('es-AR')} ${data.divisa_destino}

💱 Tasa: 1 ${data.divisa_origen} = ${(data.cantidad_destino / data.cantidad_origen).toFixed(4)} ${data.divisa_destino}

📊 Stocks actualizados
📅 ${new Date().toLocaleString('es-AR')}

¡Gracias!`
  }
};

const data = $('Validar Disponibilidad1').first().json;

return {
  json: {
    success: false,
    debe_escalar: true,
    message: data.message,
    tipo_escalamiento: data.tipo_escalamiento
  }
};

const data = $('Debe Escalar?1').item.json;

const divisa_entrada = data.divisa_origen;
const cantidad_entrada = data.cantidad_origen;
const precio_entrada = data.stockOrigen.precio_compra;

const divisa_salida = data.divisa_destino;
const cantidad_salida = data.cantidad_destino;
const precio_salida = data.stockDestino.precio_venta;

let valor_entrada_usd, valor_salida_usd;

if (divisa_entrada === 'USD') {
  valor_entrada_usd = cantidad_entrada;
} else if (divisa_entrada === 'ARS') {
  valor_entrada_usd = cantidad_entrada / precio_salida;
} else {
  valor_entrada_usd = (cantidad_entrada * precio_entrada) / precio_salida;
}

if (divisa_salida === 'USD') {
  valor_salida_usd = cantidad_salida;
} else if (divisa_salida === 'ARS') {
  valor_salida_usd = cantidad_salida / precio_salida;
} else {
  valor_salida_usd = (cantidad_salida * precio_salida) / precio_salida;
}

const tasa_cambio = cantidad_salida / cantidad_entrada;

return {
  json: {
    usuario_telegram_id: data.usuario_telegram_id,
    usuario_telegram_nombre: data.usuario_telegram_nombre,
    divisa_entrada: divisa_entrada,
    cantidad_entrada: cantidad_entrada,
    precio_entrada: precio_entrada,
    valor_entrada_usd: valor_entrada_usd,
    divisa_salida: divisa_salida,
    cantidad_salida: cantidad_salida,
    precio_salida: precio_salida,
    valor_salida_usd: valor_salida_usd,
    tasa_cambio: tasa_cambio,
    estado: 'completada',
    notas: data.notas || '',
    stockOrigen: data.stockOrigen,
    stockDestino: data.stockDestino,
    idStockOrigen: data.idStockOrigen,
    idStockDestino: data.idStockDestino,
    nuevoStockOrigen: data.nuevoStockOrigen,
    nuevoStockDestino: data.nuevoStockDestino
  }
};

const operacion = $('Registrar Operación1').item.json;

const divisa_entrada = operacion.divisa_entrada;
const cantidad_entrada = operacion.cantidad_entrada;
const precio_entrada = operacion.precio_entrada;

const divisa_salida = operacion.divisa_salida;
const cantidad_salida = operacion.cantidad_salida;
const precio_salida = operacion.precio_salida;

let ganancia_bruta_usd = 0;
let ganancia_bruta_ars = 0;
let margen_porcentaje = 0;

// Cliente entrega ARS, recibe USD
if (divisa_entrada === 'ARS' && divisa_salida === 'USD') {
  const precio_compra_usd = 1000; // Precio base de referencia
  ganancia_bruta_ars = (precio_salida - precio_compra_usd) * cantidad_salida;
  ganancia_bruta_usd = ganancia_bruta_ars / precio_salida;
  margen_porcentaje = ((precio_salida - precio_compra_usd) / precio_compra_usd) * 100;
}
// Cliente entrega USD, recibe ARS
else if (divisa_entrada === 'USD' && divisa_salida === 'ARS') {
  const valor_real_ars = cantidad_entrada * precio_entrada;
  ganancia_bruta_ars = cantidad_salida - valor_real_ars;
  ganancia_bruta_usd = ganancia_bruta_ars / precio_entrada;
  margen_porcentaje = (ganancia_bruta_ars / valor_real_ars) * 100;
}
// Otras divisas
else {
  const valor_entrada_usd = operacion.valor_entrada_usd || 0;
  const valor_salida_usd = operacion.valor_salida_usd || 0;
  ganancia_bruta_usd = valor_entrada_usd - valor_salida_usd;
  ganancia_bruta_ars = ganancia_bruta_usd * precio_salida;
  margen_porcentaje = valor_salida_usd > 0 ? (ganancia_bruta_usd / valor_salida_usd) * 100 : 0;
}

return {
  json: {
    operacion_id: operacion.id,
    numero_operacion: operacion.numero_operacion,
    ganancia_bruta_usd: ganancia_bruta_usd,
    ganancia_bruta_ars: ganancia_bruta_ars,
    margen_porcentaje: margen_porcentaje,
    tipo_ganancia: 'spread',
    ...operacion
  }
};

const data = $('Actualizar Ganancias').item.json;

return {
  json: {
    operacion_id: data.operacion_id,
    numero_operacion: data.numero_operacion,
    divisa: data.divisa_entrada,
    tipo: 'entrada',
    cantidad: data.cantidad_entrada,
    valor_usd: data.valor_entrada_usd,
    precio_usd: data.precio_entrada,
    saldo_anterior: data.stockOrigen?.stock_disponible || 0,
    saldo_nuevo: data.nuevoStockOrigen || 0,
    descripcion: `Entrada de ${data.cantidad_entrada} ${data.divisa_entrada} - Operación #${data.numero_operacion}`,
    usuario_telegram_id: data.usuario_telegram_id
  }
};

const data = $('Actualizar Ganancias').item.json;

return {
  json: {
    operacion_id: data.operacion_id,
    numero_operacion: data.numero_operacion,
    divisa: data.divisa_salida,
    tipo: 'salida',
    cantidad: data.cantidad_salida,
    valor_usd: data.valor_salida_usd,
    precio_usd: data.precio_salida,
    saldo_anterior: data.stockDestino?.stock_disponible || 0,
    saldo_nuevo: data.nuevoStockDestino || 0,
    descripcion: `Salida de ${data.cantidad_salida} ${data.divisa_salida} - Operación #${data.numero_operacion}`,
    usuario_telegram_id: data.usuario_telegram_id
  }
};

// PARSE INPUT - VERSIÓN ROBUSTA Y SIMPLE
const input = $json;

console.log('📥 INPUT RECIBIDO:', JSON.stringify(input, null, 2));

// ========================================
// 1. SI YA VIENE ESTRUCTURADO (desde herramienta)
// ========================================
if (input.divisa_origen && input.cantidad_origen && input.divisa_destino) {
  console.log('✅ Input ya estructurado');
  return { 
    json: {
      ...input,
      usuario_telegram_id: input.usuario_telegram_id || 'desconocido',
      usuario_telegram_nombre: input.usuario_telegram_nombre || 'Usuario'
    }
  };
}

// ========================================
// 2. EXTRAER TEXTO
// ========================================
let texto = (input.query || input.text || input.message || '').toString().trim();

if (!texto) {
  throw new Error('❌ No se recibió ningún texto para parsear');
}

console.log('🔍 Texto a parsear:', texto);

// Normalizar: lowercase y limpiar comas
texto = texto.toLowerCase().replace(/(\d),(\d)/g, '$1$2');

// ========================================
// 3. INTENTAR PARSEAR CON DIFERENTES PATRONES
// ========================================

// Patrón 1: "vende 200 USD recibe 290000 ARS"
let match = texto.match(/(?:vende|entrega|da)\s+(\d+\.?\d*)\s+(usd|ars|eur|btc|eth|real)\s+.*?(?:recibe|obtiene|por)\s+(\d+\.?\d*)\s+(usd|ars|eur|btc|eth|real)/i);

if (match) {
  console.log('✅ Match con patrón 1: vende-recibe');
  return {
    json: {
      cantidad_origen: parseFloat(match[1]),
      divisa_origen: match[2].toUpperCase(),
      cantidad_destino: parseFloat(match[3]),
      divisa_destino: match[4].toUpperCase(),
      usuario_telegram_id: input.usuario_telegram_id || 'desconocido',
      usuario_telegram_nombre: input.usuario_telegram_nombre || 'Usuario',
      notas: `Parseado: "${texto}"`
    }
  };
}

// Patrón 2: "200 USD por 290000 ARS"
match = texto.match(/(\d+\.?\d*)\s+(usd|ars|eur|btc|eth|real)\s+por\s+(\d+\.?\d*)\s+(usd|ars|eur|btc|eth|real)/i);

if (match) {
  console.log('✅ Match con patrón 2: cantidad-por-cantidad');
  return {
    json: {
      cantidad_origen: parseFloat(match[1]),
      divisa_origen: match[2].toUpperCase(),
      cantidad_destino: parseFloat(match[3]),
      divisa_destino: match[4].toUpperCase(),
      usuario_telegram_id: input.usuario_telegram_id || 'desconocido',
      usuario_telegram_nombre: input.usuario_telegram_nombre || 'Usuario',
      notas: `Parseado: "${texto}"`
    }
  };
}

// Patrón 3: "compra 50 USD entregando 77500 ARS"
match = texto.match(/(?:compra|adquiere|recibe)\s+(\d+\.?\d*)\s+(usd|ars|eur|btc|eth|real)\s+entregando\s+(\d+\.?\d*)\s+(usd|ars|eur|btc|eth|real)/i);

if (match) {
  console.log('✅ Match con patrón 3: compra-entregando');
  return {
    json: {
      cantidad_origen: parseFloat(match[3]), // Lo que entrega
      divisa_origen: match[4].toUpperCase(),
      cantidad_destino: parseFloat(match[1]), // Lo que recibe
      divisa_destino: match[2].toUpperCase(),
      usuario_telegram_id: input.usuario_telegram_id || 'desconocido',
      usuario_telegram_nombre: input.usuario_telegram_nombre || 'Usuario',
      notas: `Parseado: "${texto}"`
    }
  };
}

// Patrón 4: "200 USD a ARS" (calcula automáticamente)
match = texto.match(/(\d+\.?\d*)\s+(usd|ars|eur|btc|eth|real)\s+(?:a|para|->)\s+(usd|ars|eur|btc|eth|real)/i);

if (match) {
  console.log('✅ Match con patrón 4: cantidad-a-divisa');
  return {
    json: {
      cantidad_origen: parseFloat(match[1]),
      divisa_origen: match[2].toUpperCase(),
      cantidad_destino: 0, // Se calcula después
      divisa_destino: match[3].toUpperCase(),
      usuario_telegram_id: input.usuario_telegram_id || 'desconocido',
      usuario_telegram_nombre: input.usuario_telegram_nombre || 'Usuario',
      notas: `Parseado: "${texto}"`
    }
  };
}

// ========================================
// 4. NO SE PUDO PARSEAR
// ========================================
console.error('❌ Ningún patrón coincidió');

throw new Error(`❌ No pude entender el formato.

Texto recibido: "${texto}"

Formatos válidos:
- "Cliente vende 200 USD y recibe 290000 ARS"
- "200 USD por 290000 ARS"
- "Cliente compra 50 USD entregando 77500 ARS"
- "200 USD a ARS"

Divisas: USD, ARS, EUR, BTC, ETH, REAL`);
